def eulerian(n, m):
    if n == 0:
        return 1 if m == 0 else 0
    if m < 0 or m > n - 1:
        return 0

    memo = {}

    def a(n, m):
        if n == 0:
            return 1 if m == 0 else 0
        if m < 0 or m > n - 1:
            return 0
        if (n, m) in memo:
            return memo[(n, m)]
        result = (n - m) * a(n - 1, m - 1) + (m + 1) * a(n - 1, m)
        memo[(n, m)] = result
        return result

    return a(n, m)

