def solve_diophantine(a, b, n):
    def egcd(a, b):
        if a == 0:
            return (b, 0, 1)
        g, x1, y1 = egcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return (g, x, y)

    g, x0, y0 = egcd(a, b)

    if g == 0:
        if n == 0:
            return (0, 0)
        return None

    if n % g != 0:
        return None

    scale = n // g
    x = x0 * scale
    y = y0 * scale

    return (x, y)

