def sequence_count(m, n):
    if n == 0:
        return 0
    dp = [1] * (m + 1)  # dp[v]: number of sequences of current length ending at value v
    dp[0] = 0
    for _ in range(1, n):
        prefix = [0] * (m + 1)
        for v in range(1, m + 1):
            prefix[v] = prefix[v - 1] + dp[v]
        new_dp = [0] * (m + 1)
        for v in range(1, m + 1):
            limit = v // 2
            if limit >= 1:
                new_dp[v] = prefix[limit]
        dp = new_dp
    return sum(dp)

