def max_bitonic_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    inc = [0] * n
    for i in range(n):
        inc[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i] and inc[j] + arr[i] > inc[i]:
                inc[i] = inc[j] + arr[i]

    dec = [0] * n
    for i in range(n - 1, -1, -1):
        dec[i] = arr[i]
        for j in range(n - 1, i, -1):
            if arr[j] < arr[i] and dec[j] + arr[i] > dec[i]:
                dec[i] = dec[j] + arr[i]

    max_sum = 0
    for i in range(n):
        total = inc[i] + dec[i] - arr[i]
        if total > max_sum:
            max_sum = total

    return max_sum

