def paint_fence(n, k):
    if n == 0:
        return 0
    if n == 1:
        return k
    same = k
    diff = k * (k - 1)
    for _ in range(3, n + 1):
        total = same + diff
        same = diff
        diff = total * (k - 1)
    return same + diff

